def simulate_flood(inp):
    """Simulate 1s spreading through 0s in straight lines."""
    rows = len(inp)
    cols = len(inp[0])
    result = [row[:] for row in inp]

    # Directions: up, down, left, right
    dirs = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    def is_valid(r, c):
        return 0 <= r < rows and 0 <= c < cols

    changed = True
    while changed:
        changed = False
        for r in range(rows):
            for c in range(cols):
                if result[r][c] == 1:
                    for dr, dc in dirs:
                        rr, cc = r + dr, c + dc
                        while is_valid(rr, cc):
                            if result[rr][cc] == 0:
                                result[rr][cc] = 1
                                changed = True
                            else:
                                break
                            rr += dr
                            cc += dc
        for r in range(rows):
            for c in range(cols):
                if result[r][c] != inp[r][c]:
                    changed = True
                    break
            if changed:
                break

    return result

